def reconnect_if_needed(func):
    """Reopen TransportMedium if pipe is broken"""
    def wrapper(*args, **kwargs):
        """Reconnection wrapper"""
        try:
            return func(*args, **kwargs)
        except socket.error as e:
            if e.errno != errno.EPIPE:  # Not a broken pipe
                raise
            else:
                self = args[0]
                self.open()
                return func(*args, **kwargs)
    return wrapper


class TransportMedium(object):
    """Transport medium API base class"""
    __metaclass__ = abc.ABCMeta

    def __init__(self):  # tymczasowo None
        """Init TransportMedium"""
        super(TransportMedium, self).__init__()

    @abc.abstractmethod
    def open(self):
        """Abstract open method"""
        return

    @abc.abstractmethod
    def close(self):  # TODO: call it from __del__()
        """Abstract close method"""
        return

    @abc.abstractmethod
    def send(self, data):
        """Abstract send method"""
        return

    def receive(self, timeout=30):
        """Receive method"""
        data = None
        return data


class AsyncTCPTransportMedium(TransportMedium):
    """Transport medium using TCP sockets"""

    def __init__(self, port, host="localhost", receive_buffer_size=64 * 4096, logger=None):
        """Init TCPTransportMedium"""
        super(AsyncTCPTransportMedium, self).__init__()
        self.host = host
        self.port = port
        self.receive_buffer_size = receive_buffer_size
        self.logger = logger
        self.socket = None
        self.blocking = 1
        if self.logger:
            self.logger.debug("CONSTRUCTED: {}".format(self.__class__.__name__))

        self.reader = None  # asyncio.StreamReader
        self.writer = None  # asyncio.StreamWriter

    def __del__(self):
        if self.logger:
            self.logger.debug("DELETED: {}".format(self.__class__.__name__))

    async def open(self):
        """Transport medium - connection openning"""
        self.logger.debug(f"Attempting to connect to {self.host}:{self.port}...")
        self.reader, self.writer = await asyncio.open_connection(self.host, self.port)
        self.logger.debug(f"Successfully connected to {self.host}:{self.port}.")

    async def close(self):
        """Transport medium - connection closing"""
        if self.writer:
            self.logger.info(f"Closing connection to {self.host}:{self.port}...")
            self.writer.close()
            await self.writer.wait_closed()
            self.logger.info("Connection closed.")
        else:
            self.logger.debug("No active connection to close.")

    async def send(self, data):
        if self.writer is None:
            self.logger.warning("Attempted to send data before connecting or after disconnection.")
            raise ErrRemoteEndpointDisconnected("Not connected to remote endpoint.")

        data_to_send: bytes
        if isinstance(data, str):
            data_to_send = data.encode('utf-8')
        else:
            data_to_send = data

        self.writer.write(data_to_send)
        await self.writer.drain()

    async def receive(self):
        return await asyncio.wait_for(self.reader.read(self.receive_buffer_size), timeout=None)


class TCPTransportMedium(TransportMedium):
    """Transport medium using TCP sockets"""

    def __init__(self, port, host="localhost", receive_buffer_size=64 * 4096, logger=None):
        """Init TCPTransportMedium"""
        super(TCPTransportMedium, self).__init__()
        self.host = host
        self.port = port
        self.receive_buffer_size = receive_buffer_size
        self.logger = logger
        self.socket = None
        self.blocking = 1
        if self.logger:
            self.logger.debug("CONSTRUCTED: {}".format(self.__class__.__name__))

    def __del__(self):
        if self.logger:
            self.logger.debug("DELETED: {}".format(self.__class__.__name__))

