    #             return 1
    #         except socket_error as serr:
    #             if (serr.errno == 10061):
    #                 if self.logger:
    #                     self.logger.debug_print(info="Retry to connect, echo server is still down",
    #                                             owner="{{%s}}" % self.__class__.__name__)
    #             else:
    #                 raise

    def open(self):
        """Transport medium - connection openning"""
        try:
            self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            if sys.platform.startswith('java'):  # Program runs under Jython
                self.blocking = 0  # Jython  limitation
            self.socket.setblocking(self.blocking)
            self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 4 * 1024 * 1024)
            self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 1 * 1024 * 1024)
            # FUTURE: maybe we change to non-blocking sockets on select inside threads
            #         but for now any call to RPC is blocking send-receive
            #             self.socket.setblocking(0)  # optional non-blocking
            #             CHECK_TIMEOUT = 0.01
            #             self.socket.settimeout(CHECK_TIMEOUT)
            self.socket.connect((self.host, self.port))
            if self.logger:
                self.logger.debug("OPEN: Connected to TCP {}:{} by {}".format(self.host, self.port, self.__class__.__name__))

        except Exception:
            raise

    def close(self):
        """Transport medium - connection closing"""
        if self.socket is not None:
            self.socket.close()
            self.socket = None
            if self.logger:
                self.logger.debug("CLOSED: {}".format(self.__class__.__name__))

    @reconnect_if_needed
    def send(self, data):
        """Transport medium - send data"""
        try:
            self._send_try(data)
        except socket_error as serr:
            TCPTransportMedium._send_except(data, serr)

    def _send_try(self, data):
        debug_info = "CANNOT send"
        ready = select.select([], [self.socket], [], 0.01)
        if ready[1]:
            if isinstance(data, string_types):
                self.socket.send(data.encode('utf-8'))
            else:
                self.socket.send(data)
            debug_info = "send    "
        if self.logger:
            msg_len = len(data) if data else 0
            self.logger.debug("{}: msg_len={}, data={}".format(debug_info, msg_len, data))

    @staticmethod
    def _send_except(data, serr):
        if (serr.errno == 10054) or (serr.errno == 10053):
            raise ErrRemoteEndpointDisconnected(
                "[Transport Layer] Remote Endpoint Closed detected during send msg '%s'" % data)
        else:
            raise

    @staticmethod
    def _handle_socket_error(socket_error):
        """Helper function - error handling"""
        if (socket_error.errno == 10054) or (socket_error.errno == 10053):
            raise ErrRemoteEndpointDisconnected("[Transport Layer] Remote Endpoint Closed Socket Gently")
        elif (socket_error.errno == 10061):
            raise ErrRemoteEndpointDead("[Transport Layer] Remote Endpoint Terminated")
        else:
            raise socket_error

    def _receive_data(self):
        """Helper function - data receive"""
        try:
            data = self._try_to_receive_data()
        except socket_error as serr:
            self._handle_socket_error(serr)
        else:
            if not data:
                raise ErrRemoteEndpointDisconnected("[Transport Layer] Remote Endpoint Closed Socket Gently")
        try:  # TODO: Rework "pass" in try/except block
            return data
        except UnboundLocalError:
            pass

    def _try_to_receive_data(self):
        data = self.socket.recv(self.receive_buffer_size)
        if self.logger:
            msg_len = len(data) if data else 0
            self.logger.debug("received: msg_len={}, data={}".format(msg_len, data))
        return data

    def receive(self):  # TODO: UT all cases: timeout, socket errors, endpoint disconnected
        """Transport medium - receive data"""
        timeout = 30
        ready = select.select([self.socket], [], [], timeout)
        if ready[0]:
            d = self._receive_data()
            return d
        else:
            return b''
